export function life(u){
u('visual',7,1,'色彩、構圖與視覺重點','色相區分顏色種類，明度描述亮暗，彩度描述鮮豔程度。構圖藉比例、對比、留白和視線引導形成重點。','海報主題以較大的文字、高明度對比呈現，其他資訊縮小並分組，讓讀者先掌握重點。','顏色越多不代表越清楚；低對比文字可能難以閱讀。','製作一張社團海報，限用三種主要顏色，請同學說出第一眼看見什麼。',[
['描述色彩「亮或暗」的是？',['色相','明度','節拍','透視'],1,'明度是色彩明暗程度；色相是顏色類別。'],
['海報資訊太雜亂，優先改善哪項？',['把所有字放大','建立主次層級並保留空間','增加更多顏色','把背景改成密集花紋'],1,'資訊層級與留白讓視線能找到重點。']]);
u('visual',8,1,'透視、媒材與創作過程','線性透視以地平線、消失點及物體大小變化表現空間。媒材具有不同質感與操作特性；創作可經觀察、草圖、實作與修訂。','觀察筆直道路，遠處看起來變窄，平行線在畫面中朝消失點聚合。','透視是呈現空間的方法之一，不是所有藝術都必須遵守同一寫實規則。','畫教室角落，標示視平線；再以拼貼做同主題，比較兩種媒材的效果。',[
['單點透視中，部分平行線在畫面中朝何處聚合？',['隨機點','消失點','最高亮點','紙張四角'],1,'消失點協助呈現空間深度。'],
['創作草圖後發現重點不明，較好的做法？',['不可更改','透過試作與回饋調整','全部怪觀眾','只換簽名'],1,'修訂是創作過程的一部分，可檢查作品是否傳達意圖。']]);
u('visual',9,2,'藝術賞析、文化與策展','賞析先描述看見的形式，再分析如何產生效果，連結文化脈絡後提出有證據的詮釋。策展需設定主題、選件、動線與說明。','同樣是人物肖像，不同構圖、材質與時代可能帶出不同權力、身分或情感觀點。','「我不喜歡」是感受，但還不是完整分析；不要把單一文化標準當唯一尺度。','策劃三件作品的小展覽，為每件寫 80 字說明並列明創作者與來源。',[
['藝術評論要更具說服力，應？',['只說漂亮','用作品可觀察的形式支持解釋','猜作者私生活','只看售價'],1,'從構圖、色彩、媒材等證據連到詮釋，可讓他人理解判斷。'],
['策展主題的主要作用為何？',['讓作品毫無關係','建立選件與展示的共同脈絡','只決定門票','取代所有作品'],1,'主題幫助觀眾理解不同作品之間的關係。']]);

u('music',7,1,'節奏、拍號與旋律','拍是穩定脈動，節奏是長短音的組合。常見 4/4 拍以四分音符為一拍，每小節四拍。旋律由音高與節奏組織而成。','4/4 拍一個全音符占四拍；一個二分音符占兩拍，可與兩個四分音符組成一小節。','速度快慢不同於節拍數；4/4 不表示每秒四拍。','拍出四拍循環，設計一小節節奏並讓同學模仿。',[
['4/4 拍的一個二分音符通常占？',['半拍','一拍','兩拍','四拍'],2,'四分音符為一拍，二分音符長度是兩拍。'],
['4/4 拍每小節的總拍數為？',['2','3','4','8'],2,'分子 4 表示每小節四拍。']]);
u('music',8,1,'音色、合奏與聆聽','音色使同音高的不同樂器聽起來不同。合奏需聆聽節拍、音量平衡、起止與彼此角色。欣賞音樂也可注意主題如何重複與變化。','主旋律出現時，伴奏可調整音量讓旋律清楚；輪到不同聲部時再改變平衡。','合奏不是每個人都盡量大聲；音高、音量、音色是不同面向。','用身邊安全物件組成節奏合奏，設定一位指揮並練習同步結束。',[
['同音高的鋼琴與小提琴仍可辨識，主要因？',['只有拍號不同','音色不同','音名不同','一定速度不同'],1,'不同振動方式和泛音組成形成音色差異。'],
['合奏中伴奏蓋過主旋律時，應？',['全員更大聲','調整音量並聆聽彼此','停止看指揮','每人各自加速'],1,'聲部平衡需要主動聆聽與調整。']]);
u('music',9,2,'音樂文化與創作','不同社群透過音樂傳達記憶、儀式與生活經驗。創作可從短動機出發，運用重複、對比與變化形成段落。','以兩小節動機 A 開始，接對比段 B，再回到 A，形成簡單 ABA 結構。','不應把非西方音樂視為較低等，也不以單一曲目代表整個文化。','創作八小節節奏或旋律，標出重複和對比處，說明想表達的情境。',[
['ABA 曲式的最後一段通常？',['回到 A 的素材','一定無聲','必須完全無關','改為四種樂器'],0,'ABA 的第三段回應第一段主題，可能有變化。'],
['認識一種傳統音樂，應同時了解？',['只看排行榜','演出情境與文化脈絡','只看音量','禁止比較'],1,'使用情境、社群與歷史有助理解音樂意義。']]);

u('performing',7,1,'身體、聲音與舞臺空間','表演透過身體姿態、聲音、節奏與空間傳達角色和關係。不同距離、視線與停頓會改變觀眾的理解。','同一句「你來了」，搭配退後、微笑或長停頓，可呈現不同關係與情緒。','大聲不等於有情感；肢體與聲音需要配合情境。','用同一句台詞呈現期待、驚訝、失望三種情境，請同學說明看見的線索。',[
['同一句台詞可呈現不同情緒，主要透過？',['只改字體','聲調、節奏、表情與姿態','只靠服裝價格','完全不用情境'],1,'表演的非文字線索會影響觀眾理解。'],
['舞臺走位設計需要注意？',['觀眾視線與演員關係','只有鞋子顏色','越擠越好','每次都背對觀眾'],0,'空間安排能呈現焦點、關係並維持可見性。']]);
u('performing',8,1,'角色、衝突與即興','角色有目標與阻礙，衝突推動情節。即興需要聆聽搭檔提供的資訊，接受情境再發展，兼顧界線與合作。','角色想把遺失的書還給主人，卻只剩五分鐘，目標和時間限制形成戲劇張力。','衝突不一定是吵架，也可以是內心抉擇或環境阻礙。','兩人即興演出「遲到前的一次幫忙」，先設定目標、阻礙與安全界線。',[
['戲劇中的衝突可以是？',['只有打架','角色目標遇到阻礙','一定要有反派','沒有任何選擇'],1,'內在、人物間與環境阻力都能形成衝突。'],
['合作即興時，最重要的是？',['完全忽略搭檔','聆聽並回應已有情境','每句都否定對方','只記自己的台詞'],1,'即興依賴互相接收與延伸資訊。']]);
u('performing',9,2,'展演製作與回饋','展演包含文本、表演、燈光、音效、舞臺與行政協作。排練需檢查節奏、轉場與安全，回饋應描述觀察並提出可操作建議。','「第三場轉場時觀眾看不到主角，試把位置向前移」比「演得很差」更具體。','完成演出不代表不需檢討；技術效果也不能取代故事與合作。','製作三分鐘短劇，分工、排練並記錄一次根據回饋做出的修改。',[
['哪種回饋最可操作？',['很爛','不喜歡','第二句太快，試在轉折前停半拍','你永遠不會演'],2,'指出具體位置、現象和調整方式才能協助改進。'],
['排練轉場時首先要兼顧？',['速度與人員安全','只要夠暗','器材越多越好','不需要分工'],0,'轉場必須協調路線與器材，避免碰撞並維持演出節奏。']]);

u('computing',7,1,'演算法與問題拆解','演算法是解決問題的明確步驟，應可執行、可檢驗並在合理條件下結束。可把大問題拆成輸入、處理、輸出與較小任務。','找三數最大值：先設最大值為第一數，再依序比較其餘數，較大就更新。','「做得更好」不夠明確，電腦需要可判斷的規則。','用流程圖畫出判斷奇偶的演算法，包含輸入與兩種輸出。',[
['演算法最需要哪項特性？',['步驟模糊','規則明確可執行','永不結束','只能寫英文'],1,'明確步驟才能被執行和驗證。'],
['判斷整數 n 是否偶數，合適條件是？',['n 大於 10','n 除以 2 的餘數為 0','n 是正數','n 有兩位數'],1,'整數能被 2 整除，即餘數為 0，是偶數。']]);
u('computing',8,1,'變數、條件與迴圈','變數儲存資料，條件選擇執行路徑，迴圈重複處理。追蹤變數每一步的值，可以找出程式錯誤。','sum＝0；依序將 1、2、3 加入 sum，得到 6。先初始化再累加，避免使用未定義的值。','賦值不是數學等式；x＝x＋1 在程式中表示把舊值加一再存回。','手動追蹤迴圈將 1 到 5 加總，每次記錄 sum。',[
['x 初值 2，執行 x＝x＋3 兩次後為？',['5','6','8','10'],2,'第一次變 5，第二次變 8。'],
['sum 初值 0，累加 1 到 4，最後為？',['4','6','10','24'],2,'0＋1＋2＋3＋4＝10。']]);
u('computing',9,2,'資料、網路與資訊安全','資料表示方式影響儲存和運算；網路傳送資訊需透過協定。數位安全從獨立密碼、更新、來源查證及最少必要資料開始。','收到要求立即登入的連結，先自行開啟已知官方網站核對，而不是輸入帳號密碼。','https 代表傳輸加密，不保證網站經營者值得信任。','為一份問卷刪掉不需要的個資欄位，說明資料用途及保存方式。',[
['收到陌生登入連結，較合宜的是？',['直接輸入密碼','從已知官方入口確認','把驗證碼傳給對方','分享給全班試試'],1,'獨立開啟官方入口可降低釣魚連結風險。'],
['看到網站使用 https，可確定什麼？',['商品一定真實','傳輸使用加密機制','不會有詐騙','所有內容都正確'],1,'加密保護傳輸，不等於內容或經營者可信。']]);

u('technology',7,1,'設計需求與工程流程','設計從使用者需求和限制開始，經構想、選案、製作、測試與修正。評估標準應事先設定，避免只看作品外觀。','設計書架可設定承重、尺寸、穩定與材料成本等條件，再比較方案。','第一個想法不一定最好；測試失敗是修改的資訊。','為桌面收納提出兩種方案，以容量、可取用性與材料用量比較。',[
['設計前最應先做？',['直接切材料','釐清需求與限制','先挑最貴工具','只看網路外觀'],1,'需求與限制決定設計方向及成功標準。'],
['原型測試不符合承重需求，應？',['隱藏結果','分析原因並修正再測','宣布完成','只改顏色'],1,'測試提供改進證據，工程流程包含迭代。']]);
u('technology',8,1,'結構、機構與材料','結構支撐負載，機構傳遞或轉換運動。材料需依強度、重量、加工性及環境影響選擇。三角形支架常用於提升穩定性。','矩形框架可能變形，加上斜撐形成三角形，可改善平面內穩定。','材料越硬不代表在所有情況越好，還需看韌性、重量與用途。','用紙條製作矩形與加斜撐框架，以相同推力比較變形。',[
['矩形框架加斜撐的主要目的？',['增加裝飾字','提高形狀穩定性','使所有力消失','一定減少材料'],1,'斜撐形成三角形，限制框架剪切變形。'],
['腳踏車齒輪與鏈條主要用來？',['把運動完全消除','傳遞運動與調整速比','測量氣溫','儲存資料'],1,'傳動機構將踩踏的運動傳到車輪並可調整速比。']]);
u('technology',9,2,'能源、製造與永續產品','能源系統將能量轉成所需形式，過程有損失。產品評估要看使用功能、製造、維修與廢棄處理；設計可降低用料並延長使用年限。','可更換零件的檯燈，故障時能修理而不必丟棄整件，減少材料浪費。','再生能源不是完全沒有環境影響；必須比較實際條件。','拆解一件不通電的廢棄包裝，提案減量或重複使用，不操作帶電設備。',[
['讓產品容易維修，通常有助於？',['延長使用壽命','保證永不損壞','增加一次性浪費','取消所有材料'],0,'可維修性減少因小零件故障而整件廢棄。'],
['能源轉換效率是指？',['輸出有用能量占輸入能量比例','機器顏色','只有總重量','使用者數量'],0,'效率比較有用輸出與總輸入，需使用一致能量單位。']]);

u('health',7,1,'青春期、自我認識與身體界線','青春期的身心變化有個別差異。尊重自己與他人的身體界線，溝通須清楚、自由且可改變心意。遇到不舒服的互動可尋求可信任成人協助。','同學說不想被拍照，應先停止，而不是因「大家都拍」就忽略他的感受。','沒有反抗不等於同意；身體發展速度不同不表示價值不同。','練習一句清楚表達界線的說法，列出可以求助的校內成人。',[
['同學說不想被拍照，應？',['尊重並停止拍攝','趁他不注意拍','說大家都可以','強迫他微笑'],0,'尊重明確表達的身體與影像界線。'],
['青春期發展的合理觀念是？',['每個人一定同時變化','存在個別差異','越早越優秀','可以用嘲笑促進成長'],1,'發展時間與速度有差異，不應以此評價個人。']]);
u('health',8,1,'飲食資訊與健康選擇','飲食選擇需考慮多樣性、適量與生活情境。閱讀包裝要確認每份含量、每包份數與營養標示，不以廣告口號代替資料。','一包飲料有兩份，每份糖 12 g，喝完整包是 24 g，不能只記每份數字。','單一食品不能代表整體飲食；「天然」不保證任何情況都合適。','比較兩款食品營養標示，用相同份量列出差異，避免評斷同學身材。',[
['每包 3 份、每份糖 8 g，吃完整包糖量？',['8 g','11 g','16 g','24 g'],3,'3×8＝24 g，需要乘上實際食用份數。'],
['比較食品營養標示前，應確認？',['包裝顏色','份量與每包份數','代言人','廣告音樂'],1,'基準份量不同時，不能直接比較標示數值。']]);
u('health',9,2,'健康資訊、風險與求助','健康訊息應檢查發布者、更新時間與證據。遇到身心困擾可向家長、導師、輔導老師或專業人員求助。緊急情境依在地緊急服務與現場專業指示處理。','網路貼文說一種產品能治所有病，缺乏可信證據，應向合格專業人員核實。','別把同學經驗當每個人的診斷，也不要憑網路測驗自行認定疾病。','為校園健康傳言設計查證表：誰說、證據、日期、可諮詢誰。',[
['「一瓶治百病」廣告最需要？',['立即購買','查證證據與合格專業意見','大量轉傳','只看留言好評'],1,'誇大宣稱須以可信來源與專業判斷核實。'],
['同學長期受情緒困擾，較好的支持方式？',['嘲笑他','傾聽並協助連結可信任成人或專業支持','要求保證永不求助','公開他的秘密'],1,'支持與適當求助能讓同學獲得更多協助。']]);

u('pe',7,1,'動作學習與自我監測','運動學習以適合自己的起點、漸進練習與回饋為原則。準備活動、場地檢查與對身體訊號的覺察都是參與的一部分。','學習投擲可先練站姿與揮臂，再加入步伐；記錄命中率與動作感受，而非只比較別人成績。','練得越累不一定越有效；疼痛不是進步的必要條件。','在教師指導下選一個動作，記錄起點、練習方式與一次具體改善。',[
['學新動作較合理的方式？',['直接做最高難度','由基本動作漸進並取得回饋','忽略場地','只比同學'],1,'分解與漸進有助建立動作控制。'],
['運動時出現明顯不適，應？',['硬撐到底','停止並向教師或適當人員反映','嘲笑自己','增加強度'],1,'身體訊號需要被注意，由適當人員評估後續處理。']]);
u('pe',8,1,'球類策略與團隊合作','球類不只有個人技術，也包含空間、傳接、攻防轉換與決策。觀察空位及隊友位置，選擇能幫助團隊的行動。','傳球後移動到空位能提供新的接應點；防守時溝通分工可減少重複盯同一人。','持球越久不代表貢獻越大；失誤可分析原因而非責怪個人。','在簡化比賽中觀察三次有效傳球，說明接應者如何創造空間。',[
['傳球後較有利的行動？',['站著不動','移動到合適空位接應','跑出場外','背對所有隊友'],1,'移動提供傳球選項並創造空間。'],
['團隊失分後，較有助改善的是？',['互相責怪','討論站位與分工','立即拒絕合作','只看誰最受歡迎'],1,'具體檢討策略與分工，有助改善下一回合。']]);
u('pe',9,2,'運動計畫與公平競賽','計畫應考慮個人狀況、活動偏好、時間及可觀察的目標。公平競賽包含遵守規則、尊重對手與誠實回報，並能欣賞不同能力的參與。','把「變強」改成「兩週內完成四次適合自己的技巧練習，每次記錄一項改進」，較容易執行與反思。','運動表現不等於人的價值；包容與安全參與比羞辱式排名重要。','制定兩週個人活動計畫，與教師確認適切性，記錄調整而非只追求次數。',[
['較容易檢核的運動學習目標是？',['永遠第一','有日期、次數與具體動作的計畫','越痛越好','完全不記錄'],1,'具體可觀察的行為與時間讓計畫可追蹤。'],
['公平競賽包括？',['為贏故意隱瞞違規','尊重規則、對手與不同能力者','嘲笑失敗者','只接受自己獲勝'],1,'運動精神同時重視競賽與尊重。']]);

u('home',7,1,'家庭合作與生活管理','家庭工作可依時間、能力與需求協商分配，不應固定由某性別承擔。生活管理包含整理、採買、計畫與照顧，也需要評估無形負擔。','安排晚餐不只有烹調，還包含盤點食材、規劃、採買與清潔；分工要看見整段工作。','「幫忙」不應掩蓋共同責任；不同家庭型態都值得尊重。','列出一週家務及所需時間，與家人協商一項可承擔的責任。',[
['合理家務分工應根據？',['固定性別','時間、能力與共同協商','只看年紀最大者','誰最安靜就全做'],1,'分工應配合實際條件並尊重成員。'],
['規劃採買清單屬於家務嗎？',['不算，只有動手才算','算，是生活管理的工作','只有付錢才算','永遠不用分工'],1,'規劃與協調也是時間和心力投入。']]);
u('home',8,1,'飲食製備與衣物照護','生活技能需要讀懂標示、選擇工具並安排流程。食材處理注意清潔與生熟分開；衣物照護依纖維特性及洗標，不是一律高溫。','料理前先看步驟、備妥器具；衣物標示不可漂白時不任意加漂白劑。','昂貴工具不能代替正確流程；衣物處理方式不只看外觀。','在成人或教師指導下規劃一道簡單餐點流程，或整理三件衣物的照護標示。',[
['處理生熟食材時，應？',['共用未清洗器具','生熟分開並適當清潔','只看顏色','所有食材放一起'],1,'分開處理可降低交叉污染風險。'],
['清洗不熟悉材質衣物前先看？',['價格','洗滌照護標示','代言人','朋友衣服顏色'],1,'照護標示提供適合該衣物的處理方式。']]);
u('home',9,2,'消費規劃與資源管理','消費前區分需要與想要，考量預算、使用頻率、維修與總成本。紀錄可幫助發現支出模式，目標需保留調整空間。','低價但常需更換的物品，總成本可能高於耐用商品；每次使用成本可作比較之一。','打折不表示一定有需要；不能只比較標價而忽略耗材。','規劃一筆有限預算，列必要支出、可選支出與保留額。',[
['商品 A 300 元可用 100 次，每次使用成本？',['0.3 元','3 元','30 元','300 元'],1,'300÷100＝3 元。'],
['看到限時折扣，先問什麼較合理？',['是否真的需要且符合預算','別人都買幾個','能不能全買','只看倒數秒數'],0,'消費需回到需求與可用資源。']]);

u('scout',7,1,'團隊分工與戶外準備','戶外活動先了解目的、路線、天氣、裝備與人員狀況，建立聯絡及備案。團隊要知道誰負責什麼，也要能互相支援。','出發前確認集合點與返程時間，若條件變差就依預先約定調整，不為了完成路線勉強前進。','看別人成功不代表自己有同樣能力和條件。','為校園定向活動寫出路線、分工、裝備與取消條件。',[
['戶外出發前最應做？',['只拍照','確認路線、天氣、人員與備案','完全不告知他人','省略裝備檢查'],1,'規劃與備案是活動安全的重要準備。'],
['現場條件超出原定安全範圍，應？',['硬完成原計畫','依備案調整或取消','隱瞞狀況','讓最年幼者獨自決定'],1,'計畫需隨真實風險調整。']]);
u('scout',8,1,'定向、地圖與環境觀察','定向需要把地圖與實地對上，辨認方向、地標及距離。指南針是輔助工具，也要理解附近金屬或磁場可能干擾讀值。','先找操場與建築等明顯地標，再讓地圖方向與實際方向一致，逐段確認位置。','只盯工具、不看環境容易迷失；電子設備也可能沒電或失去訊號。','在校內由教師安排定向路線，每個轉折都記下可辨識地標。',[
['地圖定位時，較好的起點是？',['隨機走','找已知地標對照實地','只看顏色','閉眼猜方向'],1,'已知地標建立地圖與實際位置的連結。'],
['指南針靠近大型金屬物時應注意？',['讀值可能受干擾','一定更準','不再需要地圖','南北永遠交換'],0,'磁性物體和電磁場可能影響指針。']]);
u('scout',9,2,'環境倫理與服務行動','戶外活動應減少對環境與他人的影響。服務學習包含理解需求、計畫、行動、反思與回饋，避免只為拍照而提供不符合需求的服務。','整理社區步道前先與管理者確認需求與可做範圍，活動後檢視成果和是否有意外影響。','不是看到自然物就能帶走；服務對象應有發聲和決定的空間。','設計一項校園環境行動，先訪談使用者，再設定可檢核成果。',[
['規劃服務活動的第一步應是？',['先買大量物資','了解實際需求','先安排宣傳照片','不問使用者'],1,'需求調查可避免資源浪費與不適當介入。'],
['戶外活動減少環境影響的做法？',['帶走自己的垃圾','任意摘花','刻字留念','餵食所有野生動物'],0,'妥善處理垃圾是降低干擾的基本行動。']]);

u('guidance',7,1,'認識自我與情緒表達','情緒提供需求與情境的訊息，感受本身可以被承認，行為仍需選擇。可先描述事件、感受與需求，再提出具體請求。','「你沒回覆分工訊息，我很擔心進度；希望今晚確認」比「你永遠很爛」更容易溝通。','有情緒不代表可以傷害別人；他人的一次評價也不是自我全部。','用事件、感受、需求、請求四段寫一則我訊息。',[
['哪句較符合我訊息？',['你永遠自私','我因分工未確認而擔心，希望今晚討論','大家都討厭你','你必須猜我想法'],1,'具體描述感受、原因與請求，避免人身標籤。'],
['面對情緒，較適切的做法？',['否認所有感受','辨認感受並選擇合宜行動','立刻攻擊他人','認為自己沒有價值'],1,'接納感受與管理行為可同時進行。']]);
u('guidance',8,1,'學習策略與時間規劃','自主學習包含設定目標、執行、監測與調整。提取練習是不看答案回想，間隔複習把練習分散到不同時間，錯誤可作為調整線索。','學完一個概念，先合上教材解釋，再做題檢查；隔天與幾天後再次回想，確認不是只記住剛看的句子。','閱讀時覺得熟悉不等於能獨立使用；看詳解後答對也不能當成首次掌握。','安排三次短複習，每次先回想再核對，記錄卡住的步驟。',[
['哪一項屬於提取練習？',['一直重讀同一行','不看筆記解釋觀念','只畫整頁螢光筆','只看別人答案'],1,'提取是主動從記憶中回想，而非再次接收。'],
['做錯題後最有幫助的是？',['只抄正確選項','找出錯誤原因並另找時間重做','刪掉全部紀錄','立刻認定自己不行'],1,'錯誤分析加上延後回想能檢查是否真正修正。']]);
u('guidance',9,2,'生涯探索與決策','生涯是持續探索與調整的過程，可結合興趣、能力、價值、資源與實際資訊。單次測驗提供線索，不是命運判決。','訪談某職業工作者時，詢問日常任務、訓練、困難與多種進入路徑，比只看職稱更有用。','成績或測驗不能完整決定一個人未來，也不要用性別限制選擇。','比較兩條升學路徑，列出課程、學習方式、資源與尚待查證問題。',[
['生涯測驗結果最適合視為？',['永遠不能改變的命令','自我探索的一項線索','唯一升學依據','決定人的價值'],1,'結果應與經驗、興趣和更多資訊一起討論。'],
['認識一份職業，最有幫助的問題？',['名稱好不好聽','日常工作、訓練和挑戰是什麼','制服顏色','是不是人人都喜歡'],1,'具體工作內容比表面印象更能支持選擇。']]);

u('local',7,1,'語別選擇與聆聽觀察','本土語文包含不同語別，臺灣手語亦是完整的語言。依學校開課與個人選擇學習，不能以華語直譯代替各語的發音、詞彙與語法。','同一地名在不同語言可能有不同說法，訪談時先詢問語別與使用情境，再核對官方辭典或教學資源。','本單元是共通學習方法，不是閩南語、客語、各原住民族語或手語的完整替代教材。','選定實際修習語別，向教師確認教材，記錄五個生活詞及可靠來源。',[
['學本土語文前應先確認？',['所有語別都一樣','實際修習語別與可信教材','只用華語發音','不用聽示範'],1,'不同語別有各自發音、詞彙與結構，需使用適切資源。'],
['遇到與自己不同的口音，應？',['判定錯誤並嘲笑','了解語別或腔調差異','禁止使用','一律改成華語'],1,'語言變體有其社會與地域背景，應尊重並確認使用情境。']]);
u('local',7,2,'生活對話與在地文化','語言學習需在情境中理解語氣、稱謂和互動規範。可由問候、介紹、飲食、交通等生活任務開始，透過示範、模仿、回饋累積。','訪問長輩或語言使用者前先取得同意，記錄詞語的使用情境，避免只存一串沒有說明的翻譯。','會背詞表不等於能自然互動；也不應未經同意公開他人聲音或影像。','以所學語別完成 30 秒自我介紹，請教師回饋發音、詞彙與情境合適性。',[
['錄下訪談者聲音前，應先？',['取得同意並說明用途','偷偷開錄音','上傳後再說','只要認識就不用問'],0,'錄音涉及他人的聲音與使用意願，需事先同意。'],
['提升生活對話能力，較有幫助的是？',['只背沒有語境的翻譯','在情境中練習並接受回饋','拒絕聽示範','只讀華語注音'],1,'語言能力需要情境使用與具體回饋。']]);
u('local',8,1,'臺灣手語與視覺溝通','手語透過手形、位置、動作、方向及非手部訊號組織意義，有自身語法。不同地區手語不一定相同，應向可靠教材與熟悉該語言者學習。','交流需維持視線可見，不背對對方比手語；表情可能承載語法與語意，而不只是情緒。','手語不是全球統一，也不是逐字把華語換成手勢。本站沒有以文字冒充動作示範。','觀看教師指定的臺灣手語示範，記錄視線、手部空間與表情各有何作用。',[
['關於手語，哪項正確？',['全世界完全相同','有自己的語言結構','只是隨意比手勢','不能表達抽象意思'],1,'手語是具有語法與豐富表達能力的自然語言。'],
['手語中的表情可能有什麼功能？',['完全無用','傳達語法或語意訊息','只能表示開心','只能代替手部動作'],1,'非手部訊號可參與句型與意義的表達。']]);
u('local',8,2,'語言記錄與文化行動','語言保存不只是收藏詞語，也包含支持使用、尊重說話者與記錄文化脈絡。小型專題可以從家庭稱謂、地名、故事或生活場景著手。','製作社區地名卡時，標明語別、資料來源、發音參考與受訪者同意範圍，避免自行猜測詞源。','同音不等於同源；資料不足時要標示待查，不編造歷史。','做五張在地語言卡，附來源和情境，再邀請教師校閱。',[
['推測地名來源時，應？',['只要同音就確定','查證文獻與語言使用脈絡','自己編最有趣的故事','不記錄來源'],1,'詞源需要證據，不能僅由讀音聯想判定。'],
['支持語言傳承的方式是？',['嘲笑使用者','創造尊重且可持續的使用機會','禁止不同腔調','只保存但不允許使用'],1,'語言在實際溝通與社群參與中持續發展。']]);
}
